var minimumAbsDifference = function(arr) {
    arr.sort((a, b) => a - b);

    const n = arr.length;
    let minDiff = Infinity;

    for (let i = 1; i < n; i++) {
        minDiff = Math.min(minDiff, arr[i] - arr[i - 1]);
    }

    const res = [];
    let left = 0;
    let right = 1;

    while (right < n) {
        const diff = arr[right] - arr[left];

        if (diff === minDiff) {
            res.push([arr[left], arr[right]]);
        }

        if (diff >= minDiff) {
            left++;
        } else {
            right++;
        }
    }

    return res;
};

