    let res = [];

    for (let i = 1; i < arr.length; i++) {
        const diff = arr[i] - arr[i - 1];

        if (diff < min) {
            min = diff;
            res = [[arr[i - 1], arr[i]]];
        } else if (diff === min) {
            res.push([arr[i - 1], arr[i]]);
        }
    }

